state = {"fails": 0, "opened_at": None}
def call(service_up, now, limit=5, wait=30):
    opened = state["opened_at"]
    if opened is not None and now - opened < wait:
        return "OPEN: fail fast, 0 ms"
    if service_up:                               # closed, or a half-open test
        state.update(fails=0, opened_at=None)
        return "ok, CLOSED again" if opened is not None else "ok"
    state["fails"] += 1
    if state["fails"] >= limit or opened is not None:
        state["opened_at"] = now
        return "test failed, OPEN again" if opened is not None else "timeout, trips to OPEN"
    return "timeout " + str(state["fails"]) + " of " + str(limit)
for now, up in zip([0, 2, 4, 6, 8, 9, 40, 75], [False] * 7 + [True]):
    print(f"t={now:>2}s ->", call(up, now))
